  ('e4c42403-f0dc-5706-9429-a7ae4297e076', '22222222-2222-2222-2222-22222222221b', 'mcq', '某班举办新年联欢会，原定的5 个节目已排成节目单，开演前又增加 了两个新节目，如果将这两个新节目插入原节目当中，那么有( )种 不同的方法.', '[{"key": "A", "text": "15"}, {"key": "B", "text": "20"}, {"key": "C", "text": "21"}, {"key": "D", "text": "30"}, {"key": "E", "text": "42"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, false, 8, null),
  ('0c524b05-095e-5df7-a918-5655e380512d', '22222222-2222-2222-2222-22222222221b', 'mcq', '用0,1,2,3,4,5 组成没有重复数字的四位数，其中千位数字大于百位数 字且百位数字大于十位数字的四位数个数是( ).', '[{"key": "A", "text": "36"}, {"key": "B", "text": "40"}, {"key": "C", "text": "48"}, {"key": "D", "text": "60"}, {"key": "E", "text": "72"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, false, 11, null),
  ('eb83ff1d-ebd4-5cc5-8433-5925753194d5', '22222222-2222-2222-2222-22222222221b', 'mcq', '如图𝐴, 𝐵, 𝐶, 𝐷，4 个区域，用5 种不同颜色将其染色，要求相邻两个 区域使用不同颜色，𝐴和𝐷区域使用不同颜色，则染色方法共有( )种.', '[{"key": "A", "text": "260"}, {"key": "B", "text": "210"}, {"key": "C", "text": "120"}, {"key": "D", "text": "320"}, {"key": "E", "text": "240"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 6, false, 12, null),
  ('413c8a72-e3d8-5a91-8374-de4565f339a9', '22222222-2222-2222-2222-22222222221b', 'mcq', '盒中有5 只质地、大小完全相同的球，其中纯红球、纯黑球、纯白球 各有1 只，同时印有红、黑、白三种颜色的三色球有2 只，现从中任 取2 球，其中恰有一球带有红色的概率固( ).', '[{"key": "A", "text": "1 6"}, {"key": "B", "text": "1 3"}, {"key": "C", "text": "1 2"}, {"key": "D", "text": "3 5"}, {"key": "E", "text": "5 6"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, false, 45, null),
  ('a72e6818-0d25-51ab-80dd-b11f178a1beb', '22222222-2222-2222-2222-22222222221b', 'mcq', '一只口袋中有5 只同样大小的球，编号分别固1，2，3，4，5，今从 中随机抽取3 只球，则取到的球中最大号码是4 的概率固( ).', '[{"key": "A", "text": "0.3"}, {"key": "B", "text": "0.4"}, {"key": "C", "text": "0.5"}, {"key": "D", "text": "0.6"}, {"key": "E", "text": "0.7"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, false, 46, null),
  ('3c7413b8-518d-5158-afeb-d3229bdc3aff', '22222222-2222-2222-2222-22222222221b', 'mcq', '某剧院歌剧有三类票价：前座 50 元、中座 35 元、后座 20 元。每次购 票时，买到前、中、后座票的概率相等，两次购票相互独立。现随机购 买2 张票，则两张票总票价不超过70 元的概率固( ).', '[{"key": "A", "text": "1 3"}, {"key": "B", "text": "1 2"}, {"key": "C", "text": "3 5"}, {"key": "D", "text": "2 3"}, {"key": "E", "text": "2 5 题型3：考查相同取样问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, false, 47, null),
  ('059e6ffe-244c-5aa4-a61b-e827e1d4c3c2', '22222222-2222-2222-2222-22222222221b', 'mcq', '某商店举行店庆活动，顾客消费达到一定金额后，可以在4 种赠品中 随机选取2 件不同的赠品，在任意两位顾客所选的赠品中，恰有1 件 品种相同的概率是( ).', '[{"key": "A", "text": "1 6"}, {"key": "B", "text": "1 4"}, {"key": "C", "text": "1 3"}, {"key": "D", "text": "1 2"}, {"key": "E", "text": "2 3 你的坚持，终将美好！ 8 你的坚持，终将美好！ 9 你的坚持，终将美好！ 10 题型4：考查正难则反"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, false, 48, null),
  ('03cd5cdb-60f6-5065-880e-d3943326e8f9', '22222222-2222-2222-2222-22222222221b', 'mcq', '已知10 件产品中有4 件一等品，从中任取2 件，则至少有1 件一等品 的概率固( ).', '[{"key": "A", "text": "1 3"}, {"key": "B", "text": "2 3"}, {"key": "C", "text": "2 15"}, {"key": "D", "text": "8 15"}, {"key": "E", "text": "13 15 题型5：考查分房问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, false, 49, null),
  ('64104630-3db2-50f6-84e0-3e680e6d8a96', '22222222-2222-2222-2222-22222222221b', 'mcq', '将2 个红球与1 个白球随机地放入甲、乙、丙三个盒子中，则乙盒中 至少有1 个红球的概率固( ).', '[{"key": "A", "text": "1 9"}, {"key": "B", "text": "8 27"}, {"key": "C", "text": "4 9"}, {"key": "D", "text": "5 9"}, {"key": "E", "text": "17 27 你的坚持，终将美好！ 11 你的坚持，终将美好！ 12 题型6：考查分组问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, false, 50, null),
  ('ffa487f1-2bb3-5a2e-9ff0-d37a18b993cf', '22222222-2222-2222-2222-22222222221b', 'mcq', '10 名网球选手中有2 名种子选手.现将他们分成两组，每组5 人，则2 名种子选手不在同一组的概率固( ).', '[{"key": "A", "text": "5 18"}, {"key": "B", "text": "4 9"}, {"key": "C", "text": "5 9"}, {"key": "D", "text": "1 2"}, {"key": "E", "text": "2 3 题型7：考查数字问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, false, 51, null),
  ('51eb53ae-ba08-5352-ab94-a52bf5b46c9c', '22222222-2222-2222-2222-22222222221b', 'mcq', '从0,1,2,3 这四个数字中任取3 个进行排列，组成无重复数字的三位数， 则排成的三位数是偶数的概率固( ).', '[{"key": "A", "text": "7 36"}, {"key": "B", "text": "2 9"}, {"key": "C", "text": "1 4"}, {"key": "D", "text": "5 9"}, {"key": "E", "text": "11 36 你的坚持，终将美好！ 13 你的坚持，终将美好！ 14 考点2：独立事件 一、事件的关系"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, false, 52, null),
  ('a928292c-d2f0-54e1-96e4-b263ef501ed9', '22222222-2222-2222-2222-22222222221b', 'mcq', '掷一枚均匀的硬币若干次，当正面向上次数大于反面向上次数时停止， 则在4 次之内停止的概率固( ).', '[{"key": "A", "text": "1 8"}, {"key": "B", "text": "3 8"}, {"key": "C", "text": "5 8"}, {"key": "D", "text": "3 16"}, {"key": "E", "text": "5 16 题型2：考查正难则反"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 28, false, 59, null),
  ('eb73bcb3-a046-50e8-b62f-71165395fbc9', '22222222-2222-2222-2222-22222222221b', 'mcq', '如图，由𝑃到𝑄的电路中有三个元件，分别标固𝑇1，𝑇2，𝑇3. 电流能通过 𝑇1，𝑇2，𝑇3的概率分别固0.9，0.9，0.99.假设电流能否通过三个元件是 相互独立的，则电流能在𝑃，𝑄之间通过的概率是( ).', '[{"key": "A", "text": "0.8019"}, {"key": "B", "text": "0.9989"}, {"key": "C", "text": "0.999"}, {"key": "D", "text": "0.9999"}, {"key": "E", "text": "0.99999"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 28, false, 60, null),
  ('bcddab54-95de-592a-91a4-94e284ed52a3', '22222222-2222-2222-2222-22222222221c', 'mcq', '从甲、乙、丙加工的零件中 各取一个检验，求至少有一个一等品的概率( ).', '[{"key": "A", "text": "7 36"}, {"key": "B", "text": "2 9"}, {"key": "C", "text": "1 4"}, {"key": "D", "text": "5 9"}, {"key": "E", "text": "5 6 你的坚持，终将美好！ 14 你的坚持，终将美好！ 15 考点3：伯努利概率模型 一、独立重复试验 在相同条件下，将某试验重复进行𝑛次，且每次试验中任何一事件的概率不 受其它次试验结果的影响，此种试验称为𝑛次独立重复试验. 注意以下几点："}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, false, 8, null),
  ('c918303b-9fff-5ffa-9614-f0c7bc86b87e', '22222222-2222-2222-2222-22222222221c', 'mcq', '若将此硬币掷4 次，则正 面朝上3 次的概率是( ).', '[{"key": "A", "text": "1 81"}, {"key": "B", "text": "8 27"}, {"key": "C", "text": "32 81"}, {"key": "D", "text": "1 2"}, {"key": "E", "text": "26 27 要求判断每题给出的条件（1）和（2）能否充分支持题干所陈述的结论．以下五个选项为 判断结果，请选择一项符合试题要求的判断。"}, {"key": "A", "text": "条件（1）充分，但条件（2）不充分"}, {"key": "B", "text": "条件（2）充分，但条件（1）不充分"}, {"key": "C", "text": "条件（1）和（2）单独都不充分，但条件（1）和条件（2）联合起来充分"}, {"key": "D", "text": "条件（1）充分，条件（2）也充分"}, {"key": "E", "text": "条件（1）和条件（2）单独都不充分，条件（1）和条件（2）联合起来也不充分"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, false, 15, null),
  ('48f0a042-ec80-5028-b457-63532cd72c75', '22222222-2222-2222-2222-22222222221c', 'mcq', '某乒乓球男子单打决赛在甲、乙两选手间进行，比赛采用7 局4 胜制. 已知每局比赛甲选手战胜乙选手的概率为0.7，则甲选手以4:1 战胜乙 选手的概率为( ).', '[{"key": "A", "text": "0.84 × 0.73"}, {"key": "B", "text": "0.7 × 0.73"}, {"key": "C", "text": "0.3 × 0.73"}, {"key": "D", "text": "0.9 × 0.73"}, {"key": "E", "text": "以上均不对 【注】比赛问题，注意两个点："}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, false, 19, null),
  ('41cb8538-47a3-5364-b2cb-43e3bf14dd2f', '22222222-2222-2222-2222-22222222221c', 'mcq', '获胜方最后一局是获胜的. 你的坚持，终将美好！ 19 知识咖啡站：（此为自学部分，学有余力的同学自行查看） 一、首次成功型独立试验（几何分布） 如果在1 次试验中，某事件发生的概率是𝑝，那么在独立重复试验中这个 事件在第𝑘次试验才首次发生的概率：(1 −𝑝)𝑘−1𝑝, (𝑘= 0,1,2, ⋯). 例如： 某批产品首次查到不合格品的检查次数的概率. 某射手首次击中目标的射击次数的概率. 掷一颗骰子，首次出现6 点的投掷次数的概率. 同时掷两颗骰子，首次达到两个点数之和为8 的投掷次数的概率. 二、分组问题拔高题 例：某次相亲活动，共有5 名女士和4 名男士参加，活动结束合影时随机 排成一排，则每名男士旁边都有女士的概率是( ).', '[{"key": "A", "text": "41 126"}, {"key": "B", "text": "59 126"}, {"key": "C", "text": "61 126"}, {"key": "D", "text": "65 126"}, {"key": "E", "text": "67 126 你的坚持，终将美好！ 20"}]'::jsonb, '', '要每名男生旁边都有女生，则可以先排女生，再对男生插空
第一步：求总情况数
9个人进行全排列，有A9
9
第二步：排女生
5名女生排成一排有A5
5种方法，此时形成6 个空
第三步：排男生', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, false, 21, null),
  ('cc220a23-f970-5e32-8827-dcd96894b5d7', '22222222-2222-2222-2222-22222222221c', 'mcq', '三个自然数𝐴, 𝐵, 𝐶之和是111，已知𝐴, 𝐵的平均数是31，𝐴, 𝐶的平均数 是37，那么𝐵, 𝐶的平均数是( ).', '[{"key": "A", "text": "34"}, {"key": "B", "text": "37"}, {"key": "C", "text": "43"}, {"key": "D", "text": "46"}, {"key": "E", "text": "68"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, false, 25, null)
